<p class="small"><a href="/admin/users"><?= icon('back', 14) ?> All users</a></p>
<div class="two"><div>
<div class="panel"><div class="panel-b" style="display:flex;gap:16px;align-items:center"><?= avatar_html($x, 64) ?><div><h2 style="margin:0"><?= e($x['name']) ?> <?= $x['is_super'] ? badge('Super Admin', 'dark') : '' ?></h2><div class="muted"><?= e($x['email']) ?> · <?= e($x['phone']) ?></div><div class="muted small">Joined <?= e(fmt_date($x['created_at'])) ?> · last sign-in <?= $x['last_login_at'] ? e(ago($x['last_login_at'])) : 'never' ?> · email <?= $x['email_verified_at'] ? 'confirmed' : '<strong>not confirmed</strong>' ?> · 2-step <?= $x['totp_enabled'] ? 'on' : 'off' ?></div></div></div></div>
<div class="stats"><div class="stat"><b><?= $stats['courses'] ?></b><span>Course enrolments</span></div><div class="stat"><b><?= $stats['apps'] ?></b><span>Job applications</span></div><div class="stat"><b><?= $stats['posts'] ?></b><span>Community posts</span></div><div class="stat"><b><?= (int) $x['reputation'] ?></b><span>Reputation</span></div></div>
<?php if ($activity): ?><div class="panel"><div class="panel-h">Recent admin activity</div><div class="panel-b small"><?php foreach ($activity as $a) { echo '<p style="margin:0 0 6px">' . e($a['action']) . ' <span class="muted">' . e($a['entity']) . ' ' . e($a['entity_id']) . ' · ' . e(ago($a['created_at'])) . '</span></p>'; } ?></div></div><?php endif; ?></div>
<div>
<?php if (!$x['is_super']): ?><form class="panel" method="post" action="/admin/users/<?= (int) $x['id'] ?>"><?= csrf_field() ?><input type="hidden" name="action" value="roles"><div class="panel-h">Access &amp; roles</div><div class="panel-b form"><?php $have = array_filter(explode(',', $x['roles'])); foreach (ROLE_LABELS as $k => $v): ?><label class="check"><input type="checkbox" name="roles[]" value="<?= e($k) ?>" <?= in_array($k, $have, true) ? 'checked' : '' ?>><span><?= e($v) ?></span></label><?php endforeach; ?><button class="btn btn-primary btn-sm">Save access</button><p class="xs muted mb0">Untick everything to make this person a normal member again.</p></div></form><?php endif; ?>
<div class="panel"><div class="panel-h">Account actions</div><div class="panel-b"><form method="post" action="/admin/users/<?= (int) $x['id'] ?>" class="tbl-actions"><?= csrf_field() ?><button class="rowbtn" name="action" value="reset">Send password reset</button><?php if (!$x['email_verified_at']): ?><button class="rowbtn" name="action" value="verify">Mark email confirmed</button><?php endif; ?><?php if ($x['totp_enabled']): ?><button class="rowbtn" name="action" value="reset2fa" data-confirm="Remove two-step verification for this user?">Reset 2-step</button><?php endif; ?>
<?php if (!$x['is_super'] && (int) $x['id'] !== uid()): ?><button class="rowbtn" name="action" value="suspend"><?= $x['status'] === 'active' ? 'Suspend account' : 'Reactivate account' ?></button><button class="rowbtn danger" name="action" value="delete" data-confirm="Remove this user and their learning data? Their community posts are hidden. This cannot be undone.">Delete user</button><?php endif; ?></form></div></div>
</div></div>
